/* Lernpfad, Übungsmodus und praktische Bewertung. Bestehende Ansichten bleiben verfügbar. */
const kfLearnReady=()=>state.learningReady===true;
const kfLearnButton=(text,action,id='',kind='secondary')=>`<button type="button" class="button ${kind}" data-learn="${action}" data-id="${esc(id)}">${text}</button>`;
const kfLearnLevel=['Noch offen','Erklärt','Unter Anleitung','Selbstständig sicher'];
let kfChapterSelection={},kfQuizView=null,kfMatrixFilter={query:'',vehicle:'',status:''};
function kfLearnGuard(){if(!kfLearnReady())throw Error('Bitte zuerst den Haupt-GS 2.0.0 einsetzen, kfErweiterungenEinrichten ausführen und die bestehende Bereitstellung aktualisieren.');}
function kfLearnCourse(e){return (state.learningCourses||[]).find(c=>c.enrollmentId===e?.id)||byId('Courses',e?.courseId);}
function kfLearnSections(c){return (c?.sections||[]).map((s,i)=>({...s,id:s.id||'legacy-'+i}));}
function kfLearnState(e){if(e.completedAt)return {text:'Ausbildung abgeschlossen',action:'enrollment',kind:''};if(e.prerequisitesOk===false)return {text:'Vorgeschaltete Ausbildung abschließen',action:'enrollment',kind:'amber'};if(!e.theoryOk)return {text:e.theoryLearned&&e.requirements.quizRequired?'Theorieprüfung absolvieren':'Lernkapitel durcharbeiten',action:'learn',kind:'amber'};if(e.lessons<e.requirements.requiredSessions)return {text:'Nächste praktische Einschulung',action:'enrollment',kind:'amber'};if(e.skillsOk===false)return {text:'Praktische Fähigkeiten bestätigen lassen',action:'enrollment',kind:'amber'};if(e.licenceOk===false)return {text:'Führerscheinnachweis prüfen lassen',action:'enrollment',kind:'amber'};return {text:e.requirements.practicalEnabled?'Praktische Prüfung vereinbaren':'Abschluss bestätigen lassen',action:'enrollment',kind:''};}
const kfLearnCardBase=enrolCard;
enrolCard=function(e){if(!kfLearnReady())return kfLearnCardBase(e);const c=byId('Courses',e.courseId),v=byId('Vehicles',e.vehicleId),next=kfLearnState(e),skills=e.skills||[],required=skills.filter(s=>s.required),done=required.filter(s=>s.level>=3).length;return `<article class="progress-panel kf-path-card"><div class="panel-head"><div><span class="eyebrow">DEINE FAHRZEUGAUSBILDUNG</span><h3>${esc(v?.name||'Fahrzeug')}</h3><span class="small muted">${esc(c?.title||'Ausbildung')}</span></div>${tag(e.completedAt?'ABGESCHLOSSEN':'IN AUSBILDUNG',e.completedAt?'':'amber')}</div><div class="kf-path-stages">${[[e.theoryOk,'Theorie',e.requirements.quizRequired?'Mit Pflichtprüfung':'Lerninhalte'],[e.lessons>=e.requirements.requiredSessions,'Einschulungen',e.lessons+' / '+e.requirements.requiredSessions],[e.skillsOk!==false,'Fähigkeiten',required.length?done+' / '+required.length:'Nach bisherigen Vorgaben'],[!!e.completedAt,e.requirements.practicalEnabled?'Prüfung':'Abschluss',e.completedAt?date(e.completedAt):'Noch offen']].map(([ok,title,sub],i)=>`<div class="${ok?'done':''}"><b>${ok?'✓':i+1}</b><span>${title}<small>${esc(sub)}</small></span></div>`).join('')}</div><div class="kf-next-step"><small>NÄCHSTER SCHRITT</small><strong>${esc(next.text)}</strong></div><div class="vehicle-foot"><span class="help">${e.courseVersionId?'Ausbildungsfassung '+e.courseRevision:'Bestehende Anforderungen bleiben erhalten'}</span>${staff()?btn('Ausbildungsakte →','enrollment',e.id,'secondary small'):kfLearnButton('Ausbildung öffnen →','learn',e.id,'teal small')}</div></article>`;};
const kfLearnDashboardBase=dashboard;
dashboard=function(){if(!kfLearnReady()||staff()){kfLearnDashboardBase();if(kfLearnReady()&&staff()&&kfCan('viewProgress'))$('#content').insertAdjacentHTML('afterbegin',`<section class="kf-learning-banner"><div><span class="eyebrow">AUSBILDUNGSLEITUNG</span><h2>Wer ist für den nächsten Schritt bereit?</h2><p>Theorie, Fähigkeiten, Einschulungen und Nachweise gemeinsam im Blick.</p></div>${navBtn('Ausbildungsübersicht öffnen →','progress','teal')}</section>`);return;}const list=state.enrollments||[],open=list.filter(e=>!e.completedAt);$('#content').innerHTML=heading('DEIN PERSÖNLICHER AUSBILDUNGSWEG','Servus, '+(user.name.split(' ')[0]||'')+'.','Hier findest du deine Lernkapitel, Übungen und nächsten Schritte.')+`<section class="kf-learning-hero"><div><span class="eyebrow">LERNEN. ÜBEN. SICHER ANWENDEN.</span><h2>Dein nächstes Fahrzeug<br>beginnt mit dem nächsten Schritt.</h2><p>${open.length?open.length+' Fahrzeugausbildung'+(open.length===1?' ist':'en sind')+' gerade offen.':'Deine bestätigten Erfolge bleiben im Ausbildungspass gespeichert.'}</p></div><div class="kf-hero-count"><strong>${list.filter(e=>e.completedAt).length}</strong><span>Fahrzeugausbildungen<br>abgeschlossen</span></div></section>${expirySummary()}<div class="cards spacer">${list.map(enrolCard).join('')||empty('Deine Ausbildung wird vorbereitet.','Dein Ausbilder ordnet dir die Fahrzeuge zu.')}</div><section class="panel spacer"><div class="panel-head"><h2>Termine & Nachweise</h2>${navBtn('Ausbildungstermine →','trainingevents','secondary')}</div><p>Deine Führerscheine, Dokumente und Ablauf-Erinnerungen findest du weiterhin unter „Checkliste & Scheine“.</p>${navBtn('Checkliste & Scheine öffnen','profile','secondary')}</section>`;};
const kfLearnCourseReadBase=courseRead;
courseRead=function(id){if(!kfLearnReady()){kfLearnCourseReadBase(id);return;}const e=staff()?null:state.enrollments.find(e=>e.courseId===id),c=e?kfLearnCourse(e):byId('Courses',id);if(!c){navigate('courses');return;}const v=byId('Vehicles',c.vehicleId),sections=kfLearnSections(c),summary=e?.learningChapters||[],selected=kfChapterSelection[id]||summary.find(s=>!s.read)?.id||sections[0]?.id||'reference';kfChapterSelection[id]=selected;const chapter=sections.find(s=>s.id===selected),read=summary.find(s=>s.id===selected)?.read;const learner=!staff()&&!!e;$('#content').innerHTML=heading('DEIN LERNBEREICH',c.title,c.objectives,btn('← Ausbildungen','coursesBack','','secondary')+(staff()&&(kfCan('manageCourses')||kfCan('manageQuiz'))?btn('Inhalte bearbeiten','editCourse',id,'secondary'):''))+`<div class="kf-learning-layout"><aside class="panel kf-chapters"><span class="eyebrow">KAPITELÜBERSICHT</span><h2>Schritt für Schritt</h2>${sections.map((s,i)=>`<button type="button" class="kf-chapter ${selected===s.id?'active':''}" data-learn="chapter" data-id="${esc(id)}" data-chapter="${esc(s.id)}"><b>${summary.find(x=>x.id===s.id)?.read?'✓':String(i+1).padStart(2,'0')}</b><span>${esc(s.title)}<small>${s.required===false?'Vertiefung':'Lernkapitel'}</small></span></button>`).join('')||'<p class="help">Für diese Ausbildung wurden noch keine einzelnen Lernkapitel angelegt.</p>'}<button type="button" class="kf-chapter ${selected==='reference'?'active':''}" data-learn="chapter" data-id="${esc(id)}" data-chapter="reference"><b>↗</b><span>Fahrzeug nachschlagen<small>Technik, Geräteräume & Beladung</small></span></button>${e?`<p class="help spacer">${summary.filter(s=>s.read).length} / ${summary.length} Kapitel als gelesen bestätigt. Praktische Fähigkeiten bestätigt dein Ausbilder.</p>`:''}</aside><article class="panel reading kf-lesson">${chapter?`<span class="eyebrow">KAPITEL ${sections.indexOf(chapter)+1} VON ${sections.length}</span><h2>${esc(chapter.title)}</h2>${chapter.imageUrl?`<figure class="kf-lesson-image"><img src="${esc(chapter.imageUrl)}" alt="${esc(chapter.imageCaption||chapter.title)}" loading="lazy" referrerpolicy="no-referrer"><figcaption>${esc(chapter.imageCaption||'')}</figcaption></figure>`:''}<p class="prose">${esc(chapter.body)}</p>${chapter.resourceUrl?`<a class="button secondary" href="${esc(chapter.resourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(chapter.resourceLabel||'Lernunterlage öffnen')} ↗</a>`:''}<div class="form-section kf-lesson-footer">${learner?(read?'<span class="notice">✓ Kapitel als gelesen bestätigt</span>':kfLearnButton('Gelesen bestätigen & weiter →','readChapter',e.id,'teal')):'<p class="help">Vorschau des Lerninhalts. Lernbestätigungen erfolgen im persönlichen Teilnehmerprofil.</p>'}${sections.indexOf(chapter)<sections.length-1?`<button class="button secondary" type="button" data-learn="chapter" data-id="${esc(id)}" data-chapter="${esc(sections[sections.indexOf(chapter)+1].id)}">Nächstes Kapitel →</button>`:''}</div>`:`<span class="eyebrow">FAHRZEUG NACHSCHLAGEN</span><h2>${esc(v?.name||'Fahrzeug')}</h2><p class="prose">${esc(c.content||'')}</p><h3>Technische Daten</h3><p class="prose">${esc(v?.technicalData||'Noch nicht hinterlegt.')}</p><h3>Geräteräume & Bereiche</h3>${(v?.rooms||[]).map(r=>`<details class="room"><summary>${esc(r.name)} · ${(r.items||[]).length} Geräte</summary>${kfRoomBeladung(r)}</details>`).join('')}<p class="help">Fahrzeugdaten zum Nachschlagen zeigen den aktuellen Bestand. Die Lernkapitel deiner Ausbildungsfassung bleiben erhalten.</p>`}</article><aside class="panel kf-learning-actions"><span class="eyebrow">DEIN AUSBILDUNGSWEG</span><h2>Dein nächster Schritt</h2>${e?`<p>${esc(kfLearnState(e).text)}</p><div class="kf-action-stack">${learner&&!e.theoryLearned?kfLearnButton('Lerninhalte abschließen','finishLearning',e.id,'teal'):e.theoryLearned?'<span class="notice">✓ Lerninhalte bestätigt</span>':''}${learner&&c.quiz?.enabled?kfLearnButton('Wissen üben – ohne Prüfungsversuch','practice',e.id,'secondary'):''}${learner&&c.quiz?.enabled&&(!e.quizPassed||!e.requirements.quizRequired)&&!e.completedAt?kfLearnButton(e.requirements.quizRequired?'Pflichtprüfung starten':'Theoriequiz starten','formal',e.id,'teal'):''}${e.quizPassed?'<span class="notice">✓ Theoriequiz bestanden</span>':''}${e.canExam&&!e.completedAt&&e.requirements.practicalEnabled?btn('Prüfungstermin anfragen','book',e.id,'secondary'):''}${btn('Ausbildungsakte öffnen','enrollment',e.id,'secondary')}</div><p class="help spacer">${e.lessons} / ${e.requirements.requiredSessions} Einschulungen bestätigt${(e.skills||[]).length?' · '+e.skills.filter(s=>s.level>=3).length+' / '+e.skills.length+' Fähigkeiten selbstständig sicher':''}.</p>`:'<p>Nach Zuordnung sehen Teilnehmer hier ihren persönlichen Lern- und Ausbildungsstand.</p>'}${staff()?`<details class="spacer"><summary>Ausbilderunterlagen</summary><p class="help prose">${esc(c.workMaterials||'Keine zusätzlichen Arbeitsmittel.')}</p>${c.presentation?`<p><a href="${esc(c.presentation)}" target="_blank" rel="noopener noreferrer">Präsentation öffnen ↗</a></p>`:''}${(c.materials||[]).map(m=>`<p><a href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">${esc(m.name||'Dokument')} ↗</a></p>`).join('')}</details>`:''}</aside></div>`;kfMobileChapters();};

const kfLearnCourseFormBase=renderCourseForm;
renderCourseForm=function(){kfLearnCourseFormBase();if(!kfLearnReady()){$('#courseForm').insertAdjacentHTML('afterbegin','<div class="notice amber">Für Lernkapitel, praktische Fähigkeiten und Prüfungsbögen zuerst den Haupt-GS 2.0.0 aktualisieren und kfErweiterungenEinrichten ausführen.</div>');return;}const c=courseDraft,manage=kfCan('manageCourses'),quiz=kfCan('manageQuiz');(c.sections||[]).forEach((s,i)=>{const box=$(`[name="sectionTitle_${i}"]`)?.closest('.editor-box');if(box)box.insertAdjacentHTML('beforeend',`<div class="kf-chapter-options">${field('Direkter HTTPS-Bildlink (optional)','learnImage_'+i,s.imageUrl||'','url')}${field('Bildbeschreibung','learnCaption_'+i,s.imageCaption||'')}${field('Lernunterlage / Video – HTTPS-Link','learnResource_'+i,s.resourceUrl||'','url')}${field('Beschriftung des Links','learnResourceLabel_'+i,s.resourceLabel||'')}${check('Erforderliches Lernkapitel für neue Zuordnungen','learnRequired_'+i,s.required!==false)}</div>`);});const target=$('#courseForm .form-actions');target.insertAdjacentHTML('beforebegin',`<div class="form-section" id="kfPracticalEditor"><span class="eyebrow">PRAKTISCHE AUSBILDUNG</span><h3>Fähigkeiten je Fahrzeug</h3><p class="help">Ausbilder bestätigen: erklärt, unter Anleitung oder selbstständig sicher. Verbindliche Fähigkeiten gelten für neu zugeordnete Ausbildungen. Bestehende Anforderungen bleiben erhalten.</p>${kfCriteriaEditor('practicalSkills',c.practicalSkills||[])}${kfLearnButton('+ Fähigkeit','addSkill','','secondary small')}<h3 class="spacer">Praktischer Prüfungsbogen</h3><p class="help">Für neue Zuordnungen müssen alle verbindlichen Prüfungspunkte positiv bewertet werden. Mindestens ein Prüfungspunkt muss verbindlich sein.</p>${kfCriteriaEditor('examCriteria',c.examCriteria||[])}${kfLearnButton('+ Prüfungspunkt','addCriterion','','secondary small')}</div>`);if(quiz){const section=$('#questionEditors')?.closest('.form-section');if(section){section.insertAdjacentHTML('beforeend',`<div class="form-grid spacer">${field('Fragen je Theorieprüfung (0 = gesamter Pool)','learnSampleSize',c.quiz.sampleSize||0,'number','min="0" max="60"')}${check('Prüfungsfragen und Antwortreihenfolge mischen','learnShuffle',!!c.quiz.shuffle)}</div>${btn('+ Mehrfachauswahl','addQuestion','multiple','secondary small')}<p class="help spacer">Üben ist unbegrenzt und verbraucht keine Prüfungsversuche. Erklärungen werden nach Abgabe des Übungsquiz angezeigt. Bildlinks müssen direkt auf ein für die Teilnehmer erreichbares Bild zeigen.</p>`);}}if(!manage)$$('#kfPracticalEditor input,#kfPracticalEditor textarea,#kfPracticalEditor button,.kf-chapter-options input').forEach(el=>el.disabled=true);};
function kfCriteriaEditor(key,rows){return rows.map((s,i)=>`<div class="editor-box">${field('Bezeichnung *',key+'_title_'+i,s.title,'text','required')}${area('Beschreibung / Bewertungsmaßstab',key+'_description_'+i,s.description||'')}${check('Verbindlich für neue Zuordnungen',key+'_required_'+i,s.required!==false)}${kfLearnButton('Entfernen',key==='practicalSkills'?'removeSkill':'removeCriterion',String(i),'danger small')}</div>`).join('');}
const kfLearnCollectCourseBase=collectCourse;
collectCourse=function(){const before=structuredClone(courseDraft),d=new FormData($('#courseForm'));kfLearnCollectCourseBase();if(!kfLearnReady())return;if(kfCan('manageCourses')){courseDraft.sections=courseDraft.sections.map((s,i)=>({...s,id:before.sections[i]?.id||crypto.randomUUID(),imageUrl:d.get('learnImage_'+i)||'',imageCaption:d.get('learnCaption_'+i)||'',resourceUrl:d.get('learnResource_'+i)||'',resourceLabel:d.get('learnResourceLabel_'+i)||'',required:d.has('learnRequired_'+i)}));for(const key of ['practicalSkills','examCriteria'])courseDraft[key]=(before[key]||[]).map((s,i)=>({...s,title:d.get(key+'_title_'+i),description:d.get(key+'_description_'+i),required:d.has(key+'_required_'+i)}));}if(kfCan('manageQuiz')){courseDraft.quiz.shuffle=d.has('learnShuffle');courseDraft.quiz.sampleSize=Number(d.get('learnSampleSize')||0);courseDraft.quiz.questions=courseDraft.quiz.questions.map((q,i)=>{const out={...q,imageUrl:d.get('learnQuestionImage_'+i)||'',explanation:d.get('learnExplanation_'+i)||'',category:d.get('learnCategory_'+i)||''};if(q.type==='multiple'){out.correctOptions=String(d.get('learnCorrectOptions_'+i)||'').split(',').map(x=>Number(x.trim())-1).filter(Number.isInteger);}return out;});}};
const kfLearnQuestionBase=questionEditor;
questionEditor=function(q,i){if(!kfLearnReady())return kfLearnQuestionBase(q,i);const text=q.type==='multiple'?`<div class="editor-box"><div class="panel-head"><strong>Frage ${i+1} · Mehrfachauswahl</strong>${btn('Entfernen','removeQuestion',i,'danger small')}</div>${area('Fragetext','qtext_'+i,q.text)}${area('Antwortmöglichkeiten – eine pro Zeile','qoptions_'+i,(q.options||[]).join('\n'))}${field('Richtige Antwortnummern, durch Komma getrennt','learnCorrectOptions_'+i,(q.correctOptions||[0]).map(x=>x+1).join(', '))}</div>`:kfLearnQuestionBase(q,i);const extra=`<div class="kf-question-meta">${field('Themenbereich (optional)','learnCategory_'+i,q.category||'')}${field('Direkter HTTPS-Bildlink (optional)','learnQuestionImage_'+i,q.imageUrl||'','url')}${area('Erklärung für den Übungsmodus','learnExplanation_'+i,q.explanation||'')}</div>`;return `<div class="kf-question-group">${text}${extra}</div>`;};

const kfLearnEnrollmentBase=enrollmentDetail;
enrollmentDetail=function(id){kfLearnEnrollmentBase(id);if(!kfLearnReady())return;const e=byId('Enrollments',id),m=byId('Members',e?.memberId);if(!e)return;const canTeach=staff()&&kfCan('recordLessons')&&m?.userId!==user.id&&!e.completedAt;$('#modalBody').insertAdjacentHTML('beforeend',`<section class="form-section"><span class="eyebrow">PRAKTISCHE FÄHIGKEITEN</span><h3>Vom Erklären zum sicheren Anwenden</h3>${(e.skills||[]).map(s=>`<div class="kf-skill-row"><span><strong>${esc(s.title)}</strong><small>${s.required?'Verbindlich':'Vertiefung'}${s.lastCheck?' · '+esc(s.lastCheck.trainerName)+' · '+date(s.lastCheck.date):''}</small>${s.description?`<p class="help">${esc(s.description)}</p>`:''}<details class="spacer"><summary class="small">Bewertungsverlauf</summary>${(state.skillChecks||[]).filter(x=>x.enrollmentId===e.id&&x.skillId===s.id).slice().reverse().map(x=>`<p class="help">${date(x.date)} · ${esc(kfLearnLevel[x.level])} · ${esc(x.trainerName)}${x.note?' · '+esc(x.note):''}</p>`).join('')||'<p class="help">Noch keine Bewertungen.</p>'}</details></span>${tag(kfLearnLevel[s.level||0],s.level>=3?'':'amber')}${canTeach?kfLearnButton('Bewerten','skill',id+':'+s.id,'secondary small'):''}</div>`).join('')||'<p class="help">Diese Zuordnung verwendet die bisherigen Anforderungen. Neue praktische Fähigkeiten werden beim Anlegen oder Bearbeiten des Kurses für neue Zuordnungen festgelegt.</p>'}</section><section class="form-section"><h3>Prüfungsprotokolle</h3>${(state.practicalExams||[]).filter(x=>x.enrollmentId===id).sort((a,b)=>b.at.localeCompare(a.at)).map(x=>`<details class="kf-exam-record"><summary>${date(x.date)} · ${x.passed?'Positiv':'Nachschulung erforderlich'} · ${esc(x.examinerName)}</summary>${x.marks.map(mark=>`<p>${mark.passed?'✓':'○'} ${esc(mark.title)}${mark.required?'':' (Vertiefung)'}${mark.note?' · '+esc(mark.note):''}</p>`).join('')}<p class="prose">${esc(x.note||'')}</p>${x.passed&&!e.completedAt&&staff()&&kfMayExam(e.vehicleId)?kfLearnButton('Mit diesem Protokoll abschließen','completeExam',e.id+':'+x.id,'teal small'):''}</details>`).join('')||'<p class="help">Noch kein praktisches Prüfungsprotokoll hinterlegt.</p>'}</section>`);};
function kfSkillForm(id){const [eid,sid]=id.split(':'),e=byId('Enrollments',eid),skill=e?.skills?.find(s=>s.id===sid);if(!skill)throw Error('Fähigkeit nicht gefunden.');openModal('Praktische Fähigkeit bestätigen',`<form id="kfSkillForm" data-enrollment="${esc(eid)}" data-skill="${esc(sid)}" data-key="${crypto.randomUUID()}"><p>${esc(fmtName(byId('Members',e.memberId)))} · ${esc(skill.title)}</p><p class="prose help">${esc(skill.description||'')}</p>${select('Bewertungsstufe','level',[[1,'Erklärt'],[2,'Unter Anleitung durchgeführt'],[3,'Selbstständig sicher durchgeführt']],Math.max(1,skill.level||1),'required')}${field('Ausbildungsdatum','date',today(),'date',`required max="${today()}"`)}${area('Beobachtung / Hinweis für die nächste Einschulung','note','')}<p class="help">Die Bestätigung wird mit deinem Konto protokolliert. Frühere Bewertungen bleiben erhalten.</p><div class="form-actions"><button class="button teal" type="submit">Bewertung speichern</button></div></form>`);}
const kfLearnFinishBase=finishForm;
finishForm=function(id,recognition=false){const e=byId('Enrollments',id);if(!kfLearnReady()||recognition||!e?.examCriteria?.length||!e.requirements.practicalEnabled){kfLearnFinishBase(id,recognition);return;}openModal('Praktische Fahrzeugprüfung',`<form id="kfPracticalExamForm" data-enrollment="${esc(id)}" data-key="${crypto.randomUUID()}"><p>${esc(fmtName(byId('Members',e.memberId)))} · ${esc(byId('Vehicles',e.vehicleId)?.name)}</p>${!e.canExam?'<div class="notice amber">Die Voraussetzungen sind noch nicht vollständig erfüllt. Erst Theorie, Einschulungen, verbindliche Fähigkeiten und Nachweise prüfen.</div>':''}${field('Prüfungsdatum','date',today(),'date',`required max="${today()}"`)}${e.examCriteria.map((c,i)=>`<div class="editor-box"><strong>${esc(c.title)}</strong><p class="help prose">${esc(c.description||'')}${c.required?' · Verbindlicher Prüfungspunkt':' · Vertiefung'}</p>${select('Ergebnis','mark_'+i,[['','Bitte bewerten'],['yes','Positiv'],['no','Nachschulung erforderlich']],'','required')}${area('Beobachtung','markNote_'+i,'')}</div>`).join('')}${area('Gesamtbemerkung / Nachschulung','note','')}${check('Bei positivem Ergebnis Ausbildung verbindlich abschließen','complete',false)}<p class="help">Alle verbindlichen Punkte müssen positiv sein. Du kannst ein positives Protokoll zunächst speichern und den Abschluss später ausdrücklich bestätigen. Jede Prüfung bleibt nachvollziehbar.</p><div class="form-actions"><button class="button teal" type="submit" ${e.canExam?'':'disabled'}>Prüfung verbindlich dokumentieren</button></div></form>`);};
const kfLearnLessonBase=lessonForm;
lessonForm=function(id){const e=byId('Enrollments',id);if(!kfLearnReady()||!e?.skills?.length){kfLearnLessonBase(id);return;}openModal('Einschulung & Fähigkeiten dokumentieren',`<form id="kfLearningLessonForm" data-enrollment="${esc(id)}" data-key="${crypto.randomUUID()}"><p>${esc(fmtName(byId('Members',e.memberId)))} · ${esc(byId('Vehicles',e.vehicleId)?.name)}</p><div class="form-grid">${field('Datum','date',today(),'date',`required max="${today()}"`)}${field('Dauer in Minuten','minutes',60,'number','min="1" max="1440" required')}</div>${area('Ausbildungsinhalt / Bemerkung','content','')}<h3>Heute behandelte Fähigkeiten</h3>${e.skills.map((s,i)=>select(s.title,'skill_'+i,[['','Keine neue Bewertung'],['1','Erklärt'],['2','Unter Anleitung durchgeführt'],['3','Selbstständig sicher durchgeführt']],'')).join('')}<p class="help">Diese Eingabe zählt als eine Einschulung. Ausgewählte Fähigkeiten werden zusätzlich durch dich bestätigt.</p><div class="form-actions"><button class="button teal" type="submit">Einschulung & Bewertungen speichern</button></div></form>`);};
const kfLearnReportAssignmentBase=reportAssignment;
reportAssignment=function(a,x,ai,xi){const original=kfLearnReportAssignmentBase(a,x,ai,xi);if(!kfLearnReady())return original;const e=byId('Enrollments',x.enrollmentId);if(!e?.skills?.length)return original;return original+`<div class="kf-report-skills"><strong class="small">Heute behandelte Ausbildungsthemen</strong><div class="check-grid">${e.skills.map(s=>check(s.title,`learnReport_${ai}_${xi}_${s.id}`,(x.skillIds||[]).includes(s.id))).join('')}</div><p class="help">Die Themen erscheinen im Tätigkeitsbericht. Eine Kompetenzbewertung erfolgt zusätzlich durch den jeweiligen Ausbilder in der Ausbildungsakte.</p></div>`;};
const kfLearnCollectReportBase=collectReport;
collectReport=function(){const d=$('#reportForm')?new FormData($('#reportForm')):null;kfLearnCollectReportBase();if(!d||!kfLearnReady()||!reportDraft)return;reportDraft.attendees.forEach((a,ai)=>a.assignments.forEach((x,xi)=>{const e=byId('Enrollments',x.enrollmentId);x.skillIds=(e?.skills||[]).filter(s=>d.has(`learnReport_${ai}_${xi}_${s.id}`)).map(s=>s.id);}));};
const kfLearnProgressBase=progressPage;
progressPage=function(){if(!kfLearnReady()||!staff()){kfLearnProgressBase();return;}$('#content').innerHTML=heading('AUSBILDUNGSLEITUNG','Fahrzeuge & Ausbildungsstände','Jede Person, jedes Fahrzeug und der nächste erforderliche Schritt.')+`<div class="panel"><div class="kf-matrix-filters">${field('Mitglied suchen','learnMatrixQuery',kfMatrixFilter.query)}${select('Fahrzeug','learnMatrixVehicle',[['','Alle Fahrzeuge'],...state.vehicles.map(v=>[v.id,v.name])],kfMatrixFilter.vehicle)}${select('Status','learnMatrixStatus',[['','Alle Ausbildungsstände'],['open','In Ausbildung'],['ready','Prüfungsbereit'],['complete','Abgeschlossen'],['proof','Nachweise prüfen']],kfMatrixFilter.status)}</div><div id="kfMatrix"></div></div>`;const update=()=>{kfMatrixFilter={query:$('[name=learnMatrixQuery]').value,vehicle:$('[name=learnMatrixVehicle]').value,status:$('[name=learnMatrixStatus]').value};kfRenderMatrix();};$('[name=learnMatrixQuery]').oninput=update;$('[name=learnMatrixVehicle]').onchange=update;$('[name=learnMatrixStatus]').onchange=update;kfRenderMatrix();};
function kfRenderMatrix(){const f=kfMatrixFilter,members=state.members.filter(m=>(fmtName(m)+' '+m.number).toLowerCase().includes(f.query.toLowerCase())),vehicles=state.vehicles.filter(v=>!f.vehicle||f.vehicle===v.id),visible=members.filter(m=>!f.status||state.enrollments.some(e=>e.memberId===m.id&&(!f.vehicle||e.vehicleId===f.vehicle)&&(f.status==='complete'?e.completedAt:f.status==='ready'?e.canExam&&!e.completedAt:f.status==='proof'?e.licenceOk===false:!e.completedAt)));$('#kfMatrix').innerHTML=`<p class="help">${visible.length} ${visible.length===1?'Mitglied entspricht':'Mitglieder entsprechen'} der Auswahl. Prüfungsbereitschaft ersetzt keine durchgeführte Prüfung. Bestätigte Abschlüsse bleiben auch bei abgelaufenen Nachweisen erhalten.</p><div class="table-wrap kf-matrix"><table><thead><tr><th>Mitglied</th>${vehicles.map(v=>`<th>${esc(v.name)}</th>`).join('')}</tr></thead><tbody>${visible.map(m=>`<tr><th>${esc(fmtName(m))}<small>Stb. ${esc(m.number)}</small></th>${vehicles.map(v=>{const es=state.enrollments.filter(e=>e.memberId===m.id&&e.vehicleId===v.id),e=es.find(x=>!x.completedAt)||es[0];if(!e)return '<td><span class="help">Nicht zugeordnet</span></td>';return `<td><button type="button" data-action="enrollment" data-id="${esc(e.id)}" class="kf-matrix-cell ${e.completedAt?'complete':e.canExam?'ready':''}"><strong>${e.completedAt?'✓ Abgeschlossen':e.canExam?'Prüfungsbereit':'In Ausbildung'}</strong><span>Theorie ${e.theoryOk?'✓':'offen'} · Praxis ${e.lessons}/${e.requirements.requiredSessions}</span><span>${(e.skills||[]).filter(s=>s.required&&s.level>=3).length}/${(e.skills||[]).filter(s=>s.required).length} verbindliche Fähigkeiten</span>${e.licenceOk===false?'<em>Nachweis prüfen</em>':''}</button></td>`;}).join('')}</tr>`).join('')||`<tr><td colspan="${vehicles.length+1}">Keine passenden Mitglieder.</td></tr>`}</tbody></table></div>`;}

const kfLearnQuizBase=quizRender;
quizRender=function(a){if(!kfLearnReady()){kfLearnQuizBase(a);return;}kfQuizView={...a,index:0,answers:a.answers||{},enrollmentId:kfQuizView?.enrollmentId||''};kfQuizPage();};
function kfQuizPage(){const a=kfQuizView,q=a.questions[a.index];if(!q)throw Error('Keine Fragen vorhanden.');const value=a.answers[q.id];openModal(a.practice?'Übungsquiz – ohne Prüfungsversuch':'Theorieprüfung',`<form id="kfExamQuizForm"><div class="kf-quiz-top"><span>${a.practice?'ÜBEN':'PRÜFUNG'} · FRAGE ${a.index+1} / ${a.questions.length}</span><strong>${a.passPercent} % Bestehensgrenze</strong></div><div class="progress"><span style="width:${Math.round((a.index+1)/a.questions.length*100)}%"></span></div><fieldset class="question"><legend>${q.type==='multiple'?'Mehrere Antworten können richtig sein':q.type==='allocation'?'Jedes Gerät zuordnen':'Eine Antwort auswählen'}</legend><h3>${esc(q.text)}</h3>${q.imageUrl?`<img class="kf-quiz-image" src="${esc(q.imageUrl)}" alt="Abbildung zur Frage" referrerpolicy="no-referrer">`:''}${q.type==='allocation'?`<div class="kf-allocation-rows">${q.items.map(it=>select(it.name,'allocation_'+it.id,[['','Geräteraum / Bereich auswählen'],...q.rooms.map(r=>[r.id,r.name])],value?.[it.id]||'','required')).join('')}</div>`:q.options.map((o,j)=>`<label class="answer"><input type="${q.type==='multiple'?'checkbox':'radio'}" name="answer" value="${j}" ${q.type==='multiple'?(Array.isArray(value)&&value.includes(j)?'checked':''):(value===j?'checked':'')} ${q.type==='multiple'?'':'required'}>${esc(o)}</label>`).join('')}</fieldset><div class="form-actions kf-quiz-controls">${kfLearnButton('Speichern & später fortsetzen','pauseQuiz','','secondary')}${a.index?kfLearnButton('← Zurück','previousQuestion','','secondary'):''}${a.index<a.questions.length-1?kfLearnButton('Speichern & weiter →','nextQuestion','','teal'):'<button type="submit" class="button teal">'+(a.practice?'Übung auswerten':'Prüfung verbindlich abgeben')+'</button>'}</div><p class="help">Antworten werden beim Weiterblättern und beim Pausieren gespeichert. ${a.practice?'Üben verändert weder deinen Prüfungsstand noch dein Versuchslimit.':'Während der Prüfung werden keine Lösungen eingeblendet.'}</p></form>`);}
function kfCollectQuizPage(required=false){const f=$('#kfExamQuizForm'),a=kfQuizView,q=a.questions[a.index];if(required&&!f.reportValidity())return false;const d=new FormData(f);if(q.type==='allocation')a.answers[q.id]=Object.fromEntries(q.items.map(it=>[it.id,d.get('allocation_'+it.id)||'']));else if(q.type==='multiple'){const choices=d.getAll('answer').map(Number);if(required&&!choices.length){toast('Bitte mindestens eine Antwort auswählen.',true);return false;}a.answers[q.id]=choices;}else{const answer=d.get('answer');if(answer!==null)a.answers[q.id]=Number(answer);}return true;}
async function kfSaveQuizPage(){await api('saveQuizDraft',{attemptId:kfQuizView.id,practice:!!kfQuizView.practice,answers:kfQuizView.answers});}
function kfPracticeFeedback(result,eid){openModal('Deine Übungsauswertung',`<div class="result"><span class="eyebrow">ÜBEN OHNE PRÜFUNGSVERSUCH</span><h2>${result.percent} % richtig</h2><p>${result.points} / ${result.maxPoints} Punkte. Dein Ausbildungsabschluss wird dadurch nicht verändert.</p></div>${result.feedback.map((q,i)=>`<details class="editor-box" ${q.correctlyAnswered?'':'open'}><summary>${q.correctlyAnswered?'✓':'○'} Frage ${i+1}: ${esc(q.text)}</summary><p class="prose spacer">${esc(q.explanation||'Vergleiche die richtige Lösung mit dem zugehörigen Lernkapitel.')}</p><p class="help"><strong>Richtige Lösung:</strong> ${q.type==='allocation'?q.items.map(it=>esc(it.name)+' → '+esc(q.rooms.find(r=>r.id===it.correctRoomId)?.name)).join(' · '):q.type==='multiple'?(q.correctOptions||[]).map(i=>esc(q.options[i])).join(' · '):esc(q.options[q.correct])}</p></details>`).join('')}<div class="form-actions">${result.feedback.some(q=>!q.correctlyAnswered)?kfLearnButton('Fehler gezielt wiederholen','practiceWrong',eid,'teal'):''}${kfLearnButton('Noch einmal üben','practice',eid,'secondary')}${btn('Schließen','close','','secondary')}</div>`);}

if(typeof kfOwnTrainingActions!=='undefined')for(const action of ['readChapter','startPractice','submitPractice','saveQuizDraft'])kfOwnTrainingActions.add(action);
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-learn]');if(!b||b.disabled||busy)return;const action=b.dataset.learn,id=b.dataset.id||'';if(state.preview&&!['chapter','learn'].includes(action)){toast('Die Vorschau bleibt schreibgeschützt.',true);return;}try{kfLearnGuard();if(action==='learn'){const e=byId('Enrollments',id);closeModal();navigate('courses',e.courseId);}else if(action==='chapter'){kfChapterSelection[id]=b.dataset.chapter;courseRead(id);}else if(action==='readChapter'){operation(async()=>{const e=byId('Enrollments',id),c=kfLearnCourse(e),sections=kfLearnSections(c),current=kfChapterSelection[c.id],index=sections.findIndex(s=>s.id===current);await api('readChapter',{enrollmentId:id,sectionId:current});kfChapterSelection[c.id]=sections[index+1]?.id||current;await load();});}else if(action==='finishLearning'){operation(async()=>{await api('learningComplete',{enrollmentId:id});await load();toast('Lernkapitel bestätigt. Dein nächster Schritt steht im Ausbildungsweg.');});}else if(['practice','practiceWrong','formal'].includes(action)){operation(async()=>{kfQuizView={enrollmentId:id};const attempt=await api(action==='formal'?'startQuiz':'startPractice',{enrollmentId:id,wrongOnly:action==='practiceWrong'});quizRender(attempt);});}else if(['nextQuestion','previousQuestion','pauseQuiz'].includes(action)){if(!kfCollectQuizPage(action==='nextQuestion'))return;operation(async()=>{await kfSaveQuizPage();if(action==='pauseQuiz'){closeModal();toast('Antworten gespeichert. Du kannst später fortsetzen.');}else{kfQuizView.index+=action==='nextQuestion'?1:-1;kfQuizPage();}});}else if(['addSkill','addCriterion','removeSkill','removeCriterion'].includes(action)){if(!kfCan('manageCourses'))throw Error('Keine Berechtigung zum Bearbeiten der Ausbildung.');collectCourse();const key=action.includes('Skill')?'practicalSkills':'examCriteria';courseDraft[key]=courseDraft[key]||[];if(action.startsWith('add'))courseDraft[key].push({id:crypto.randomUUID(),title:'',description:'',required:true});else courseDraft[key].splice(Number(id),1);renderCourseForm();}else if(action==='completeExam'){const [eid,xid]=id.split(':'),exam=(state.practicalExams||[]).find(x=>x.id===xid&&x.enrollmentId===eid);if(!exam)throw Error('Prüfungsprotokoll fehlt.');openModal('Ausbildung abschließen?',`<p>Das positive Prüfungsprotokoll vom ${date(exam.date)} wird für den Abschluss verwendet.</p><div class="form-actions">${kfLearnButton('Ausbildung verbindlich abschließen','confirmCompleteExam',id,'teal')}</div>`);}else if(action==='confirmCompleteExam'){operation(async()=>{const [eid,xid]=id.split(':'),exam=(state.practicalExams||[]).find(x=>x.id===xid&&x.enrollmentId===eid);if(!exam)throw Error('Prüfungsprotokoll fehlt.');await api('complete',{enrollmentId:eid,date:exam.date,examPassed:true,practicalExamId:xid});closeModal();await load();enrollmentDetail(eid);toast('Fahrzeugausbildung abgeschlossen.');});}else if(action==='skill')kfSkillForm(id);}catch(e){toast(e.message,true);}});
document.addEventListener('submit',ev=>{const f=ev.target;if(!['kfSkillForm','kfPracticalExamForm','kfLearningLessonForm','kfExamQuizForm'].includes(f.id))return;ev.preventDefault();if(busy)return;if(state.preview){toast('Die Vorschau ist schreibgeschützt.',true);return;}const d=new FormData(f);if(f.id==='kfExamQuizForm'){if(!kfCollectQuizPage(true))return;const missing=kfQuizView.questions.findIndex(q=>q.type==='allocation'?q.items.some(it=>!kfQuizView.answers[q.id]?.[it.id]):q.type==='multiple'?!kfQuizView.answers[q.id]?.length:kfQuizView.answers[q.id]===undefined);if(missing>=0){kfQuizView.index=missing;kfQuizPage();toast('Bitte vor der Abgabe alle Fragen beantworten.',true);return;}}operation(async()=>{kfLearnGuard();if(f.id==='kfSkillForm'){await api('saveSkill',{enrollmentId:f.dataset.enrollment,skillId:f.dataset.skill,level:Number(d.get('level')),date:d.get('date'),note:d.get('note'),clientKey:f.dataset.key});closeModal();await load();enrollmentDetail(f.dataset.enrollment);toast('Bewertung nachvollziehbar gespeichert.');}else if(f.id==='kfPracticalExamForm'){const e=byId('Enrollments',f.dataset.enrollment),r=await api('savePracticalExam',{enrollmentId:e.id,date:d.get('date'),clientKey:f.dataset.key,note:d.get('note'),complete:d.has('complete'),marks:e.examCriteria.map((c,i)=>({id:c.id,passed:d.get('mark_'+i)==='yes',note:d.get('markNote_'+i)}))});closeModal();await load();enrollmentDetail(e.id);toast(r.passed?'Positive Prüfung dokumentiert'+(d.has('complete')?' und Ausbildung abgeschlossen.':'.'):'Prüfung dokumentiert. Nachschulungsbedarf bleibt sichtbar.');}else if(f.id==='kfLearningLessonForm'){const e=byId('Enrollments',f.dataset.enrollment);await api('learningLesson',{enrollmentId:e.id,date:d.get('date'),minutes:Number(d.get('minutes')),content:d.get('content'),clientKey:f.dataset.key,skillChecks:e.skills.flatMap((s,i)=>d.get('skill_'+i)?[{skillId:s.id,level:Number(d.get('skill_'+i))}]:[])});closeModal();await load();enrollmentDetail(e.id);toast('Einschulung und ausgewählte Fähigkeiten bestätigt.');}else if(f.id==='kfExamQuizForm'){const a=kfQuizView,r=await api(a.practice?'submitPractice':'submitQuiz',{attemptId:a.id,answers:a.answers});await load();if(a.practice)kfPracticeFeedback(r,a.enrollmentId);else openModal('Dein Prüfungsergebnis',`<div class="result"><span class="eyebrow">${r.passed?'GRATULATION':'WEITERLERNEN'}</span><h2>${r.passed?'Theorieprüfung bestanden.':'Diesmal noch nicht bestanden.'}</h2><div class="result-score">${r.percent} %</div><p>${r.points} / ${r.maxPoints} Punkte</p><p>${r.passed?'Dein Ergebnis wurde dauerhaft gespeichert.':'Nutze den Übungsmodus und die Lernkapitel zur Vorbereitung auf den nächsten Versuch.'}</p>${btn('Schließen','close','','teal')}</div>`);}});});
const kfLearningRenderBase=render;
render=function(){kfLearningRenderBase();if(user?.role==='admin'&&!state.preview&&!kfLearnReady()&&['courses','progress','dashboard'].includes(route)){const banner=document.createElement('div');banner.className='notice amber';banner.textContent='Der neue Lernbereich ist vorbereitet. Für die neuen Funktionen bitte den Haupt-GS 2.0.0 einsetzen, kfErweiterungenEinrichten ausführen und die bestehende Bereitstellung aktualisieren. Deine bisherigen Funktionen bleiben verfügbar.';$('#content').prepend(banner);}};
if(user)render();

function kfMobileChapters(){if(!window.matchMedia?.('(max-width: 760px)').matches)return;const box=$('.kf-chapters');if(!box)return;const menu=document.createElement('details'),summary=document.createElement('summary');menu.className='kf-mobile-chapter-menu';summary.textContent='Kapitel wählen';menu.append(summary);box.querySelectorAll('.kf-chapter').forEach(button=>menu.append(button));box.append(menu);}

const kfLearnApiBase=api;api=async function(action,data={}){try{return await kfLearnApiBase(action,data);}finally{if(action==='logout'){kfQuizView=null;kfChapterSelection={};}}};
